input.formText:
{
  "title": "Equipment delivery request",
  "elements": [
    {
      "type": "radiogroup",
      "name": "delivery_method",
      "title": "Delivery method",
      "choices": [
        "pickup",
        "courier"
      ]
    },
    {
      "type": "radiogroup",
      "name": "equipment_weight",
      "title": "Equipment weight",
      "choices": [
        "light",
        "heavy"
      ]
    },
    {
      "type": "boolean",
      "name": "loading_dock",
      "title": "Loading dock available"
    },
    {
      "type": "boolean",
      "name": "urgent",
      "title": "Urgent delivery"
    },
    {
      "type": "boolean",
      "name": "unloading_assistance",
      "title": "Unloading assistance",
      "visibleIf": "{delivery_method} = 'courier' and {equipment_weight} = 'heavy'",
      "isRequired": true
    },
    {
      "type": "boolean",
      "name": "handling_contact",
      "title": "Handling contact",
      "visibleIf": "{delivery_method} = 'courier' and ({equipment_weight} = 'heavy' or {loading_dock} = false)",
      "isRequired": true
    },
    {
      "type": "boolean",
      "name": "access_instructions",
      "title": "Access instructions"
    }
  ]
}

