{
  "version": 1,
  "kind": "independent-rules-v1",
  "rules": [
    {
      "field": "unloading_assistance",
      "property": "visible",
      "condition": {
        "op": "all",
        "args": [
          {
            "op": "eq",
            "field": "delivery_method",
            "value": "courier"
          },
          {
            "op": "eq",
            "field": "equipment_weight",
            "value": "heavy"
          }
        ]
      },
      "quote": "Show unloading assistance exactly for courier deliveries of heavy equipment."
    },
    {
      "field": "handling_contact",
      "property": "visible",
      "condition": {
        "op": "any",
        "args": [
          {
            "op": "all",
            "args": [
              {
                "op": "eq",
                "field": "delivery_method",
                "value": "courier"
              },
              {
                "op": "eq",
                "field": "equipment_weight",
                "value": "heavy"
              }
            ]
          },
          {
            "op": "all",
            "args": [
              {
                "op": "eq",
                "field": "delivery_method",
                "value": "courier"
              },
              {
                "op": "eq",
                "field": "loading_dock",
                "value": false
              }
            ]
          }
        ]
      },
      "quote": "Show unloading assistance exactly for courier deliveries of heavy equipment.\nShow handling contact exactly when unloading assistance is needed or a courier delivery has no loading dock."
    },
    {
      "field": "unloading_assistance",
      "property": "required",
      "condition": true,
      "quote": "Unloading assistance and handling contact are required whenever they are shown. Access instructions are optional."
    },
    {
      "field": "handling_contact",
